contracts/MatchMind.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.23;

/**
 * @title MatchMind - Football Prediction dApp on Chiliz Chain
 * @dev Stake-based prediction game with CHZ staking and yield distribution
 * @author MatchMind Team
 */

// Inlined OpenZeppelin patterns
library Address {
    function isContract(address account) internal view returns (bool) {
        return account.code.length > 0;
    }
}

library SafeMath {
    function add(uint256 a, uint256 b) internal pure returns (uint256) {
        uint256 c = a + b;
        require(c >= a, "SafeMath: addition overflow");
        return c;
    }
    
    function sub(uint256 a, uint256 b) internal pure returns (uint256) {
        require(b <= a, "SafeMath: subtraction overflow");
        return a - b;
    }
    
    function mul(uint256 a, uint256 b) internal pure returns (uint256) {
        if (a == 0) return 0;
        uint256 c = a * b;
        require(c / a == b, "SafeMath: multiplication overflow");
        return c;
    }
    
    function div(uint256 a, uint256 b) internal pure returns (uint256) {
        require(b > 0, "SafeMath: division by zero");
        return a / b;
    }
}

interface IERC20 {
    function totalSupply() external view returns (uint256);
    function balanceOf(address account) external view returns (uint256);
    function transfer(address to, uint256 amount) external returns (bool);
    function allowance(address owner, address spender) external view returns (uint256);
    function approve(address spender, uint256 amount) external returns (bool);
    function transferFrom(address from, address to, uint256 amount) external returns (bool);
    
    event Transfer(address indexed from, address indexed to, uint256 value);
    event Approval(address indexed owner, address indexed spender, uint256 value);
}

interface IChilizStaking {
    function delegate(address validator, uint256 amount) external returns (bool);
    function undelegate(address validator, uint256 amount) external returns (bool);
    function claimRewards() external returns (uint256);
    function getDelegation(address delegator, address validator) external view returns (uint256);
}

/**
 * @title GamePool
 * @dev Manages individual match staking, CHZ delegation, and yield distribution
 */
contract GamePool {
    using SafeMath for uint256;
    
    // State variables
    address public immutable owner;
    address public immutable factory;
    address public immutable chzToken;
    address public immutable stakingContract;
    address public immutable validator;
    
    uint256 public constant MINIMUM_STAKE_DURATION = 2 days;
    uint256 public constant MINIMUM_STAKE_AMOUNT = 0.01 ether; // 0.01 CHZ
    
    enum GameState { PRE_MATCH, MATCH_ACTIVE, MATCH_ENDED, DISTRIBUTED }
    GameState public gameState;
    
    struct Player {
        uint256 stakedAmount;
        uint256 stakeTime;
        uint256 yieldEarned;
        bool hasWithdrawn;
        uint256 finalRank;
    }
    
    mapping(address => Player) public players;
    address[] public playerAddresses;
    
    uint256 public totalStaked;
    uint256 public totalYield;
    uint256 public matchStartTime;
    uint256 public matchEndTime;
    
    // Events
    event PlayerStaked(address indexed player, uint256 amount, uint256 timestamp);
    event MatchStarted(uint256 timestamp);
    event MatchEnded(uint256 timestamp);
    event YieldDistributed(uint256 totalYield, uint256 playerCount);
    event PlayerWithdrawn(address indexed player, uint256 stake, uint256 yield);
    event EmergencyWithdraw(address indexed player, uint256 amount);
    
    modifier onlyOwner() {
        require(msg.sender == owner, "Only owner can call this function");
        _;
    }
    
    modifier onlyFactory() {
        require(msg.sender == factory, "Only factory can call this function");
        _;
    }
    
    modifier onlyPreMatch() {
        require(gameState == GameState.PRE_MATCH, "Game not in pre-match state");
        _;
    }
    
    modifier onlyMatchActive() {
        require(gameState == GameState.MATCH_ACTIVE, "Game not active");
        _;
    }
    
    modifier onlyMatchEnded() {
        require(gameState == GameState.MATCH_ENDED, "Game not ended");
        _;
    }
    
    constructor(
        address _owner,
        address _chzToken,
        address _stakingContract,
        address _validator
    ) {
        owner = _owner;
        factory = msg.sender;
        chzToken = _chzToken;
        stakingContract = _stakingContract;
        validator = _validator;
        gameState = GameState.PRE_MATCH;
    }
    
    /**
     * @dev Allows players to stake CHZ and enter the match
     * @param amount Amount of CHZ to stake
     */
    function stakeAndEnter(uint256 amount) external onlyPreMatch {
        require(amount >= MINIMUM_STAKE_AMOUNT, "Stake below minimum");
        require(IERC20(chzToken).balanceOf(msg.sender) >= amount, "Insufficient CHZ balance");
        require(IERC20(chzToken).allowance(msg.sender, address(this)) >= amount, "Insufficient allowance");
        
        // Transfer CHZ from player to contract
        require(IERC20(chzToken).transferFrom(msg.sender, address(this), amount), "Transfer failed");
        
        // Stake CHZ with validator
        require(IChilizStaking(stakingContract).delegate(validator, amount), "Staking failed");
        
        // Record player
        if (players[msg.sender].stakedAmount == 0) {
            playerAddresses.push(msg.sender);
        }
        
        players[msg.sender] = Player({
            stakedAmount: players[msg.sender].stakedAmount + amount,
            stakeTime: block.timestamp,
            yieldEarned: 0,
            hasWithdrawn: false,
            finalRank: 0
        });
        
        totalStaked = totalStaked + amount;
        
        emit PlayerStaked(msg.sender, amount, block.timestamp);
    }
    
    /**
     * @dev Called by backend when match starts
     */
    function startMatch() external onlyFactory onlyPreMatch {
        gameState = GameState.MATCH_ACTIVE;
        matchStartTime = block.timestamp;
        emit MatchStarted(block.timestamp);
    }
    
    /**
     * @dev Called by backend when match ends
     */
    function endMatch() external onlyFactory onlyMatchActive {
        gameState = GameState.MATCH_ENDED;
        matchEndTime = block.timestamp;
        
        // Calculate total yield from staking
        totalYield = IChilizStaking(stakingContract).claimRewards();
        
        emit MatchEnded(block.timestamp);
    }
    
    /**
     * @dev Distributes yield based on final leaderboard rankings
     * @param rankings Array of player addresses in final ranking order (1st place first)
     */
    function distributeYield(address[] calldata rankings) external onlyFactory onlyMatchEnded {
        require(gameState == GameState.MATCH_ENDED, "Match not ended");
        
        uint256 totalWeight = 0;
        uint256[] memory weights = new uint256[](rankings.length);
        
        // Calculate exponential weights
        for (uint256 i = 0; i < rankings.length; i++) {
            uint256 rank = i + 1;
            uint256 weight = 1000000 / (rank * rank); // Exponential decay: 1/rank^2
            weights[i] = weight;
            totalWeight = totalWeight + weight;
            
            // Set final rank for player
            players[rankings[i]].finalRank = rank;
        }
        
        // Distribute yield based on weights
        for (uint256 i = 0; i < rankings.length; i++) {
            address player = rankings[i];
            uint256 playerYield = (totalYield * weights[i]) / totalWeight;
            players[player].yieldEarned = playerYield;
        }
        
        gameState = GameState.DISTRIBUTED;
        emit YieldDistributed(totalYield, rankings.length);
    }
    
    /**
     * @dev Allows players to withdraw their stake and yield after minimum duration
     */
    function withdraw() external {
        Player storage player = players[msg.sender];
        require(player.stakedAmount > 0, "No stake found");
        require(!player.hasWithdrawn, "Already withdrawn");
        require(gameState == GameState.DISTRIBUTED, "Game not finished");
        require(block.timestamp >= player.stakeTime + MINIMUM_STAKE_DURATION, "Minimum stake duration not met");
        
        player.hasWithdrawn = true;
        
        // Unstake CHZ from validator
        require(IChilizStaking(stakingContract).undelegate(validator, player.stakedAmount), "Unstaking failed");
        
        // Transfer stake back to player
        require(IERC20(chzToken).transfer(msg.sender, player.stakedAmount), "Stake transfer failed");
        
        // Transfer yield to player
        if (player.yieldEarned > 0) {
            require(IERC20(chzToken).transfer(msg.sender, player.yieldEarned), "Yield transfer failed");
        }
        
        emit PlayerWithdrawn(msg.sender, player.stakedAmount, player.yieldEarned);
    }
    
    /**
     * @dev Emergency withdraw function for stuck funds
     */
    function emergencyWithdraw() external onlyOwner {
        require(gameState == GameState.DISTRIBUTED, "Game not finished");
        
        uint256 contractBalance = IERC20(chzToken).balanceOf(address(this));
        if (contractBalance > 0) {
            require(IERC20(chzToken).transfer(owner, contractBalance), "Emergency transfer failed");
        }
    }
    
    /**
     * @dev Get player information
     */
    function getPlayer(address player) external view returns (
        uint256 stakedAmount,
        uint256 stakeTime,
        uint256 yieldEarned,
        bool hasWithdrawn,
        uint256 finalRank
    ) {
        Player storage p = players[player];
        return (p.stakedAmount, p.stakeTime, p.yieldEarned, p.hasWithdrawn, p.finalRank);
    }
    
    /**
     * @dev Get all players
     */
    function getAllPlayers() external view returns (address[] memory) {
        return playerAddresses;
    }
    
    /**
     * @dev Get contract statistics
     */
    function getGameStats() external view returns (
        uint256 _totalStaked,
        uint256 _totalYield,
        uint256 _playerCount,
        GameState _gameState,
        uint256 _matchStartTime,
        uint256 _matchEndTime
    ) {
        return (totalStaked, totalYield, playerAddresses.length, gameState, matchStartTime, matchEndTime);
    }
}

/**
 * @title GameFactory
 * @dev Factory contract that deploys new GamePool contracts for each match
 */
contract GameFactory {
    address public immutable owner;
    address public immutable chzToken;
    address public immutable stakingContract;
    address public immutable validator;
    
    GamePool[] public games;
    mapping(uint256 => address) public gameAddresses;
    uint256 public gameCounter;
    
    event GameCreated(uint256 indexed gameId, address indexed gameAddress, uint256 timestamp);
    
    modifier onlyOwner() {
        require(msg.sender == owner, "Only owner can call this function");
        _;
    }
    
    constructor(
        address _owner,
        address _chzToken,
        address _stakingContract,
        address _validator
    ) {
        owner = _owner;
        chzToken = _chzToken;
        stakingContract = _stakingContract;
        validator = _validator;
    }
    
    /**
     * @dev Creates a new game pool for a match
     * @return gameId The ID of the created game
     */
    function createGame() external onlyOwner returns (uint256 gameId) {
        GamePool newGame = new GamePool(
            owner,
            chzToken,
            stakingContract,
            validator
        );
        
        gameId = gameCounter;
        games.push(newGame);
        gameAddresses[gameId] = address(newGame);
        gameCounter = gameCounter + 1;
        
        emit GameCreated(gameId, address(newGame), block.timestamp);
        return gameId;
    }
    
    /**
     * @dev Starts a specific match
     * @param gameId The ID of the game to start
     */
    function startMatch(uint256 gameId) external onlyOwner {
        require(gameId < gameCounter, "Game does not exist");
        GamePool game = GamePool(gameAddresses[gameId]);
        game.startMatch();
    }
    
    /**
     * @dev Ends a specific match
     * @param gameId The ID of the game to end
     */
    function endMatch(uint256 gameId) external onlyOwner {
        require(gameId < gameCounter, "Game does not exist");
        GamePool game = GamePool(gameAddresses[gameId]);
        game.endMatch();
    }
    
    /**
     * @dev Distributes yield for a specific match
     * @param gameId The ID of the game
     * @param rankings Array of player addresses in final ranking order
     */
    function distributeYield(uint256 gameId, address[] calldata rankings) external onlyOwner {
        require(gameId < gameCounter, "Game does not exist");
        GamePool game = GamePool(gameAddresses[gameId]);
        game.distributeYield(rankings);
    }
    
    /**
     * @dev Get all games
     */
    function getAllGames() external view returns (GamePool[] memory) {
        return games;
    }
    
    /**
     * @dev Get game address by ID
     */
    function getGameAddress(uint256 gameId) external view returns (address) {
        require(gameId < gameCounter, "Game does not exist");
        return gameAddresses[gameId];
    }
}

/**
 * @title MatchMind
 * @dev Main contract that combines GameFactory with additional utilities
 */
contract MatchMind {
    address public immutable owner;
    address public immutable chzToken;
    address public immutable stakingContract;
    address public immutable validator;
    
    GameFactory public factory;
    
    event FactoryDeployed(address indexed factoryAddress, uint256 timestamp);
    
    modifier onlyOwner() {
        require(msg.sender == owner, "Only owner can call this function");
        _;
    }
    
    constructor(
        address _chzToken,
        address _stakingContract,
        address _validator
    ) {
        owner = 0x93d43c27746D76e7606C55493A757127b33D7763;
        chzToken = _chzToken;
        stakingContract = _stakingContract;
        validator = _validator;
        
        // Deploy the factory
        factory = new GameFactory(owner, chzToken, stakingContract, validator);
        emit FactoryDeployed(address(factory), block.timestamp);
    }
    
    /**
     * @dev Creates a new game through the factory
     */
    function createGame() external onlyOwner returns (uint256) {
        return factory.createGame();
    }
    
    /**
     * @dev Starts a match through the factory
     */
    function startMatch(uint256 gameId) external onlyOwner {
        factory.startMatch(gameId);
    }
    
    /**
     * @dev Ends a match through the factory
     */
    function endMatch(uint256 gameId) external onlyOwner {
        factory.endMatch(gameId);
    }
    
    /**
     * @dev Distributes yield through the factory
     */
    function distributeYield(uint256 gameId, address[] calldata rankings) external onlyOwner {
        factory.distributeYield(gameId, rankings);
    }
    
    /**
     * @dev Emergency function to recover stuck tokens
     */
    function emergencyRecover(address token, uint256 amount) external onlyOwner {
        require(IERC20(token).transfer(owner, amount), "Transfer failed");
    }
}

