// SPDX-License-Identifier: MIT
pragma solidity ^0.8.23;

import "@openzeppelin/contracts/token/ERC20/IERC20.sol";

contract MockChilizStaking {
    mapping(address => mapping(address => uint256)) public delegations;
    mapping(address => uint256) public rewards;
    
    event Delegated(address indexed delegator, address indexed validator, uint256 amount);
    event Undelegated(address indexed delegator, address indexed validator, uint256 amount);
    event RewardsClaimed(address indexed delegator, uint256 amount);
    
    function delegate(address validator, uint256 amount) external returns (bool) {
        IERC20(msg.sender).transferFrom(msg.sender, address(this), amount);
        delegations[msg.sender][validator] += amount;
        emit Delegated(msg.sender, validator, amount);
        return true;
    }
    
    function undelegate(address validator, uint256 amount) external returns (bool) {
        require(delegations[msg.sender][validator] >= amount, "Insufficient delegation");
        delegations[msg.sender][validator] -= amount;
        IERC20(msg.sender).transfer(msg.sender, amount);
        emit Undelegated(msg.sender, validator, amount);
        return true;
    }
    
    function claimRewards() external returns (uint256) {
        uint256 reward = rewards[msg.sender];
        if (reward > 0) {
            rewards[msg.sender] = 0;
            IERC20(msg.sender).transfer(msg.sender, reward);
            emit RewardsClaimed(msg.sender, reward);
        }
        return reward;
    }
    
    function getDelegation(address delegator, address validator) external view returns (uint256) {
        return delegations[delegator][validator];
    }
    
    // Mock function to add rewards for testing
    function addRewards(address delegator, uint256 amount) external {
        rewards[delegator] += amount;
    }
}

